export const rbChesterton = pathTool({
  id: 'rb_chesterton',
  name: 'Chesterton’s Fence',
  when: 'You want to remove a process whose original purpose is unclear.',
  failureModes: [
    'Defending tradition merely because it is old',
    'Removing a control before learning its purpose',
    'Asking only the person proposing the change',
    'Treating how long something has lasted as proof that it is best'
  ],
  steps: [
    step('frame', 'Name the situation', 'Describe a current, concrete example and what you want to understand.'),
    step('apply', 'Apply this lens', 'What function did this arrangement serve, does that need remain, and what would replace the protection if you remove it?'),
    step('keep', 'What lasted', 'Which long-standing practice still serves its purpose well enough to preserve through the change? Age is a clue to usefulness and never proof of it.'),
    step('review', 'Set a small test', 'What is one proportionate next action, and what observation would make you reconsider it?')
  ],
  exercise: 'Trace one frustrating process to its original purpose before proposing a change.',
  pairsWell: ['rb_unintended'],
  chart: {
    variant: 'stages',
    stages: [
      { id: 'stage_a', label: 'Find the original function' },
      { id: 'stage_b', label: 'Check whether the need remains' },
      { id: 'stage_c', label: 'Preserve, replace or remove knowingly' }
    ]
  }
});

